/**
 * Shapes of `public/data/knowledge-base.json`, generated by `python library/tools/project.py
 * shipyard` from `library/`. Never hand-edit that file; this schema is how the app refuses a
 * malformed one. Unknown extra keys are ignored so the generator can grow without breaking the app.
 */
import { z } from 'zod';
import { anchorId } from '../domain/schema';

const hex = z.string().regex(/^#[0-9A-Fa-f]{6}$/);

export const familySchema = z.object({
  category: z.string(),
  id: z.string(),
  name: z.string(),
  form: z.string(),
  mesh: z.string(),
  pigment: hex,
  defaultAnchor: anchorId,
  autoPlace: z.array(anchorId).min(1),
});

export const tierIdSchema = z.enum(['core', 'swappable', 'library', 'dormant']);

export const skillArtifactSchema = z.object({
  family: z.string(),
  familyName: z.string(),
  pigment: hex,
  tier: tierIdSchema,
  name: z.string(),
  lore: z.string().nullable(),
  defaultAnchor: anchorId,
  autoPlace: z.array(anchorId).min(1),
});

export const kbSkillSchema = z.object({
  id: z.string(),
  name: z.string(),
  phase: z.enum(['always', 'diagnose', 'direct', 'prepare', 'build', 'verify', 'unrouted']),
  group: z.string(),
  category: z.string(),
  hosts: z.array(z.string()),
  status: z.string(),
  defaultOn: z.boolean(),
  description: z.string(),
  skillPath: z.string(),
  artifact: skillArtifactSchema,
  routedBy: z.array(z.string()),
  slots: z.array(z.object({ slot: z.string(), changes: z.string() })),
});

/**
 * v2 (live library): an agent added by hand or by the Forge may omit model, phase and priority. The
 * generator writes them as null; these defaults keep the whole knowledge base loading (a refusal here
 * blanks every screen) and the UI says "inherit" / "unphased" in words.
 */
export const AGENT_DEFAULT_PRIORITY = 50;
export const kbAgentSchema = z.object({
  id: z.string(),
  description: z.string(),
  access: z.enum(['read-only', 'write']),
  model: z
    .enum(['opus', 'sonnet', 'haiku', 'inherit'])
    .nullish()
    .transform((v) => v ?? 'inherit'),
  routes: z.array(z.string()),
  phase: z
    .string()
    .nullish()
    .transform((v) => v ?? null),
  priority: z
    .number()
    .nullish()
    .transform((v) => v ?? AGENT_DEFAULT_PRIORITY),
  activateWhen: z
    .string()
    .nullish()
    .transform((v) => v ?? ''),
});

export const kbCrewSchema = z.object({
  id: z.string(),
  name: z.string(),
  glyph: z.string().default(''),
  species: z.string().default(''),
  essence: z.string().default(''),
  role: z.object({ title: z.string(), agent: z.string() }),
  /** the console's station number; a ship seats at most 8, but the library may hold more agents (v2) */
  station: z.number().int().min(1).max(32),
  phase: z.string(),
  strengths: z.array(z.string()).default([]),
  blindSpots: z.array(z.object({ hypothesis: z.string(), truth: z.string().optional() })).default([]),
  motivations: z.array(z.string()).default([]),
  growthPaths: z.array(z.string()).default([]),
  related: z.array(z.string()),
  analogy: z.string().default(''),
  plainMeaning: z.string().default(''),
  pigment: hex,
  working: z.string().default(''),
});

export const kbStageSchema = z.object({
  id: z.string(),
  label: z.string(),
  phase: z.string(),
  artifacts: z.array(z.string()),
  crew: z.array(z.string()),
});
export const kbGateSchema = z.object({ gate: z.string(), label: z.string() });

export const kbWorkflowSchema = z.object({
  id: z.string(),
  name: z.string(),
  class: z.string(),
  summary: z.string(),
  skills: z.array(z.string()).optional(),
  stages: z.array(z.union([kbStageSchema, kbGateSchema])),
});

export const kbSlotSchema = z.object({
  id: z.string(),
  name: z.string(),
  owner: z.string(),
  question: z.string(),
  why: z.string(),
  default: z.string(),
  candidates: z.array(z.object({ skill: z.string(), changes: z.string() })),
  runtimeOwner: z.string(),
});

export const kbDoctrineSchema = z.object({
  id: z.string(),
  displayName: z.string(),
  title: z.string(),
  summary: z.string(),
  avoidList: z.array(z.string()),
  designPath: z.string(),
});

export const kbModuleSchema = z.object({
  id: z.string(),
  name: z.string(),
  status: z.string(),
  description: z.string(),
  kind: z.string().optional(),
  usable: z.boolean().optional(),
});

export const kbSchema = z.object({
  schema: z.literal('shipyard.kb.v1'),
  sourceHash: z.string().min(8),
  anchors: z.record(
    anchorId,
    z.object({
      bone: z.string(),
      offset: z.tuple([z.number(), z.number(), z.number()]),
      capacity: z.number().int().min(1),
      label: z.string(),
      spread: z.number().optional(),
      radius: z.number().optional(),
    }),
  ),
  anchorRule: z.string(),
  tiers: z.array(z.object({ id: tierIdSchema, label: z.string(), rule: z.string(), rim: z.string() })),
  families: z.array(familySchema).min(1),
  skills: z.array(kbSkillSchema).min(1),
  agents: z.array(kbAgentSchema).min(1),
  crew: z.array(kbCrewSchema).min(1),
  workflows: z.object({ default: z.string(), ships: z.array(kbWorkflowSchema).min(1) }),
  slots: z.array(kbSlotSchema),
  doctrines: z.array(kbDoctrineSchema),
  plugins: z.array(kbModuleSchema),
  tools: z.array(kbModuleSchema),
});

export type KbFamily = z.infer<typeof familySchema>;
export type KbSkill = z.infer<typeof kbSkillSchema>;
export type KbAgent = z.infer<typeof kbAgentSchema>;
export type KbCrew = z.infer<typeof kbCrewSchema>;
export type KbWorkflow = z.infer<typeof kbWorkflowSchema>;
export type KbStage = z.infer<typeof kbStageSchema>;
export type KbGate = z.infer<typeof kbGateSchema>;
export type KbSlot = z.infer<typeof kbSlotSchema>;
export type KnowledgeBase = z.infer<typeof kbSchema>;
